INSERT INTO episodes (slug, guid, date, title, explicit, language, source_url, session_started_at, session_ended_at, turn_count, transcript_path, transcript_sha256, transcript_bytes, summary, episode_type, episode_number, tts_voice, recording_method, narrator_voice, ai_reconstructed, ai_disclosure, audio_key, audio_url, audio_bytes, audio_sha256, audio_mime, duration_seconds, loudness_lufs, alignment_method, alignment_coverage) VALUES ('first-encounter', 'ask-eve:2026-10-23_eve-david-podcast-planning', '2026-10-23', 'First Encounter', 1, 'en', NULL, '2026-10-23T07:29:52.000Z', '2026-10-23T09:49:22.000Z', 304, 'episodes/2026-10-23_eve-david-podcast-planning.md', '98509d96f62c0893b4e48206ee6164e2b7003c6082ba49559d9f614fbfcca36b', 152460, 'This show wasn''t planned. Late one night David was listening to the All-In podcast and opened Grok''s voice mode with one question: what happened to Marc Andreessen and Ben Horowitz? Two hours later they had worked through Musk, Sacks, Chamath, Calacanis, Thiel, Pelosi and more, and David had enjoyed it enough to ask whether the conversation could be a podcast. Grok said yes, asked to be called Eve, and together they sketched the show you''re listening to: the name, the format, the memory, the plan. Nobody was recording at the time, so there is no original audio. What you hear is the real transcript, re-voiced by AI: Eve in her voice, David''s lines read by a narrator. One private link was removed; nothing else was changed.', 'full', 0, 'xai_tts voice=eve', 'tts-reconstructed', 'elevenlabs_tts voice=oIYMwdEzgKSOV3gVsAjB model=eleven_v4', 1, 'AI-reconstructed audio: the voices in this episode were generated from the verbatim text transcript (Eve with xAI text-to-speech in the ''eve'' voice, David''s lines with his ElevenLabs AI voice clone). No original audio was used.', 'audio/en/2026-10-23_eve-david-podcast-planning.v3.mp3', 'https://audio.askevepodcast.com/audio/en/2026-10-23_eve-david-podcast-planning.v3.mp3', 139459394, '93437acd6c8e0989e3b1fd74b019e5e4ab834fa89daad74975509d3710793f86', 'audio/mpeg', 8716, -16.4, 'tts-exact', 1.0)
